\begin{lemma}[Formalization support for Lemma~\ref{lem:ld-sandwich}]
	\label{lem:sandwich-product-average}
	\lean{MIPStarRE.QPBT.SandwichProduct.avgOver_distribution_prod}
	\leanok
	This formalization-only auxiliary isolates the iterated expectation used in
	the evaluation step of \cite[Fact~4.34]{Natarajan2018NEEXP}. For finite distributions
	$\mu,\nu$ and a real-valued function $f$,
	\[
		\mathbb E_{(x,y)\sim\mu\times\nu}f(x,y)
		=\mathbb E_{x\sim\mu}\mathbb E_{y\sim\nu}f(x,y).
	\]
\end{lemma}
\begin{proof}
	\leanok
	Expand the product distribution and rearrange its finite double sum.
\end{proof}

